class Exercise {
    // 값이 바뀌는 줄을 실행 결과와 비교해요.
    static String run(int id) {
        // ID는 목록 위치와 다르게 유지해요.
        var ids=new java.util.ArrayList<>(java.util.List.of(1,3,5));
        ids.removeIf(value->value!=id);
        // 나머지 항목은 그대로 남아야 해요.
        return ids.toString();
    }
}
